  {const ids=cardStableIds("dv:",DVOCAB,v=>cardFp(v[0]),CARD_LEGACY.dv);DVOCAB.forEach((v,i)=>add({id:ids[i],type:"dterm",sys:"derm",ref:i,label:v[0],topic:"dterm:"+v[1]}));}
