     const warn=!ss?"":s.spec>=90&&!(p>=CARD_LR_IN)&&p!=null?` A high specificity alone is not enough: with a sensitivity of ${s.sens}%, LR+ is only ${p}.`:s.sens>=90&&!(n<=CARD_LR_OUT)&&n!=null?` A high sensitivity alone is not enough: with a specificity of ${s.spec}%, LR− is only ${n}.`:"";
